public class TryCatchBasics {
    public static void main(String[] args) {
        int numerator = 50;
        int denominator = 0;

        try {
            System.out.println("Attempting division: " + numerator + " / " + denominator);
            int result = numerator / denominator; // Throws ArithmeticException
            System.out.println("Result: " + result); // SKIPPED!
        } catch (ArithmeticException e) {
            System.err.println("Caught exception: Cannot divide by zero!");
            System.err.println("Exception message: " + e.getMessage());
        }

        System.out.println("Program continues execution normally after catch block.");
    }
}

public class ControlFlowVisualizer {
    public static void main(String[] args) {
        System.out.println("Step 1: Before try block");

        try {
            System.out.println("Step 2: Inside try - before risky operation");
            int[] numbers = {1, 2, 3};
            int val = numbers[10]; // Throws ArrayIndexOutOfBoundsException!
            System.out.println("Step 3: This line NEVER executes!");
        } catch (ArrayIndexOutOfBoundsException e) {
            System.out.println("Step 4: Inside catch block - Handled: " + e.getClass().getSimpleName());
        }

        System.out.println("Step 5: After try-catch block - program continues safely.");
    }
}

