public class MultiCatchVisualizer {
    public static void process(String data) {
        try {
            int val = Integer.parseInt(data);
            int res = 50 / val;
            System.out.println("Processed: " + res);
        } catch (NumberFormatException | ArithmeticException e) {
            // Java 7+ multi-catch syntax: parameter 'e' is implicitly final
            System.err.println("Specific calculation error: " + e.getMessage());
        } catch (Exception e) {
            // General catch-all fallback must come LAST
            System.err.println("Unexpected general error: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        process("0");   // Caught by ArithmeticException
        process("xyz"); // Caught by NumberFormatException
    }
}

